INSERT INTO captains (id, name, description, phone, whatsApp, avatar, isAvailable, tripsCount, serviceTypes) VALUES ('captain_1787926145958', 'سوبر دليفري ', 'خدمة توصيل🛵 شاملة  (مطاعم🧑‍🍳،سوبر ماركت🛒 ،خضار وفواكه🥗، منظفات 🫧 شحن كهرباء💡 وماء🚰،صيدليات 💉💊،توصيل اشخاص داخل وخارج مغاغة 🧍🏼‍♂️) مواعيد شغلي في الصيف من الساعه 1:00  مساء حتى الساعه حتى الساعه 3:00 صباحا في الشتاء المواعيد دي بتتغير ', '01033838169', '01033838169', 'https://drive.google.com/file/d/18Sh3GyiIxUptiC4O2LWKi1cf_AEKzf1N/view?usp=drive_link', 1, 0, '["توصيل طلبات","مشاوير"]');
INSERT INTO captains (id, name, description, phone, whatsApp, avatar, isAvailable, tripsCount, serviceTypes) VALUES ('captain_1787927447077', 'دليفري  سريعة', 'خدمة توصيل شاملة 🛵 لكل احتياجاتك داخل وخارج مغاغة، من المطاعم والسوبر ماركت للخضار والفواكه والمنظفات والصيدليات، بالإضافة لخدمات شحن الكهرباء والمياه ', '01141961256', '01123282488', 'https://drive.google.com/file/d/1lC8qvXluZq7gsvPLhEwCj-t-vCMFKzU0/view?usp=drive_link', 1, 0, '["توصيل طلبات"]');
INSERT INTO captains (id, name, description, phone, whatsApp, avatar, isAvailable, tripsCount, serviceTypes) VALUES ('captain_1787933167120', 'دليفري طلبات ', 'خدمة دليفري سريعة 🛵⚡ اطلب اللي محتاجه وإحنا نوصلّه لحد باب بيتك، من المطاعم والطلبات اليومية لحد الصيدليات والسوبر ماركت، وكمان توصيل الأشخاص داخل وخارج مغاغة. طلبك علينا… وراحتك تهمنا ❤️', '01153929411', '01030291748', 'https://drive.google.com/file/d/1PdqPNEFfVBXMj5KobZYT4-zysuxV_cui/view?usp=drive_link', 1, 0, '["توصيل طلبات"]');
